function saveHackathon(s,id=randomUUID()) {const sql=`INSERT INTO hackathon_events(id,slug,name,event_type,summary,description,organizer,organizer_url,official_url,registration_url,start_at,end_at,registration_deadline,country,city,address,format,audience_json,tracks_json,eligibility,team_size,participation_cost,prize_pool,program_json,latitude,longitude,location_precision,status,cancellation_note,source_url,source_label,last_verified_at,verification_status,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,name=excluded.name,event_type=excluded.event_type,summary=excluded.summary,description=excluded.description,organizer=excluded.organizer,organizer_url=excluded.organizer_url,official_url=excluded.official_url,registration_url=excluded.registration_url,start_at=excluded.start_at,end_at=excluded.end_at,registration_deadline=excluded.registration_deadline,country=excluded.country,city=excluded.city,address=excluded.address,format=excluded.format,audience_json=excluded.audience_json,tracks_json=excluded.tracks_json,eligibility=excluded.eligibility,team_size=excluded.team_size,participation_cost=excluded.participation_cost,prize_pool=excluded.prize_pool,program_json=excluded.program_json,latitude=excluded.latitude,longitude=excluded.longitude,location_precision=excluded.location_precision,status=excluded.status,cancellation_note=excluded.cancellation_note,source_url=excluded.source_url,source_label=excluded.source_label,last_verified_at=excluded.last_verified_at,verification_status=excluded.verification_status,updated_at=CURRENT_TIMESTAMP`;db.prepare(sql).run(id,s.slug,s.name,s.event_type,s.summary,s.description,s.organizer,s.organizer_url,s.official_url,s.registration_url,s.start_at,s.end_at,s.registration_deadline,s.country,s.city,s.address,s.format,JSON.stringify(s.audience),JSON.stringify(s.tracks),s.eligibility,s.team_size,s.participation_cost,s.prize_pool,JSON.stringify(s.program),s.latitude,s.longitude,s.location_precision,s.status,s.cancellation_note,s.source_url,s.source_label,s.last_verified_at,s.verification_status);db.prepare('DELETE FROM hackathon_event_categories WHERE event_id=?').run(id);for(const slug of s.category_slugs)db.prepare('INSERT INTO hackathon_event_categories(event_id,category_slug) VALUES(?,?)').run(id,slug);return id;}
