   const st=path.match(/^\/api\/admin\/startups\/([^/]+)$/);if(st&&method==='PATCH'){const x=validateStartup(await body(req));db.prepare('UPDATE startups SET name=?,tagline=?,description=?,industry=?,city=?,country=?,stage=?,website=?,source=?,source_label=?,country_of_origin=?,country_of_registration=?,team_location=?,activity_geography=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(x.name,x.tagline,x.description,x.industry,x.city,x.country,x.stage,x.website,x.source,x.source_label,x.country_of_origin,x.country_of_registration,x.team_location,x.activity_geography,st[1]);audit(u,'update','startup',st[1]);json(res,200,{ok:true});return true;}if(st&&method==='DELETE'){db.prepare("UPDATE startups SET status='draft',updated_at=CURRENT_TIMESTAMP WHERE id=?").run(st[1]);audit(u,'unpublish','startup',st[1]);json(res,200,{ok:true});return true;}
