function adminHash(pass){const salt=randomBytes(16).toString('hex');return `${salt}:${scryptSync(pass,salt,64).toString('hex')}`;}
if(process.argv[2]==='admin:create'){const email=cleanText(process.argv[3],254).toLowerCase(),password=process.argv[4]||'';if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||password.length<12||password.length>200){console.error('Использование: node server.mjs admin:create email@example.com "пароль от 12 до 200 символов"');process.exit(1);}try{db.prepare('INSERT INTO admins(id,email,password_hash,role) VALUES(?,?,?,?)').run(randomUUID(),email,adminHash(password),'admin');console.log(`Администратор создан: ${email}`);}catch{console.error('Этот email уже зарегистрирован.');process.exit(1);}process.exit(0);}
const server=createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');if(url.pathname.startsWith('/api/')){await api(req,res,url);return;}if(req.method!=='GET'&&req.method!=='HEAD'){json(res,405,{error:'Метод не поддерживается'});return;}let p=normalize(decodeURIComponent(url.pathname).replaceAll('\\','/')).replaceAll('\\','/');if(p==='/'||p==='\\')p='/index.html';if(/^\/hackathons(?:\/(?:events|map|calendar|archive|organizers|about|[^/]+))?$/.test(p))p='/hackathons.html';if(READ_ONLY_DEPLOYMENT&&p==='/admin.html'){res.writeHead(503,{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff'});res.end('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Админка отключена · Startup Hub</title><body style="font:16px system-ui;max-width:620px;margin:12vh auto;padding:24px;color:#17251c"><h1>Админка временно отключена</h1><p>Эта опубликованная версия Startup Hub работает в режиме просмотра. Каталог стартапов и хакатонов доступен без изменений.</p><a href="/">Вернуться в каталог →</a></body></html>');return;}if(!PUBLIC_FILES.has(p)){res.writeHead(404,{'X-Content-Type-Options':'nosniff'});res.end('Not found');return;}const file=resolve(ROOT,'.'+p),rootPrefix=ROOT+(process.platform==='win32'?'\\':'/');if(file!==ROOT&&!file.startsWith(rootPrefix)){json(res,403,{error:'Запрещено'});return;}if(!existsSync(file)){res.writeHead(404);res.end('Not found');return;}res.writeHead(200,{'Content-Type':MIME[extname(file)]||'application/octet-stream','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','X-Frame-Options':'DENY','Content-Security-Policy':"default-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://unpkg.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: blob: https://*.tile.openstreetmap.org https://unpkg.com https://hackathon.kz https://api.hackathon.kz https://astanahub.vc; connect-src 'self' https://*.tile.openstreetmap.org https://unpkg.com; script-src 'self' https://unpkg.com"});res.end(readFileSync(file));}catch(e){json(res,e.status||500,{error:e.status?e.message:'Внутренняя ошибка сервера'});if(!e.status)console.error(e);}});
server.listen(PORT,()=>console.log(`KAZAI running at http://localhost:${server.address().port}`));
